mapper.select:
SELECT ASSESSMENT_ID, BILL_NUMBER, BILL_AMOUNT, RISK_LEVEL, RISK_TYPE, ACCEPTOR_NAME, ASSESSMENT_STATUS, MATURITY_DATE, RISK_SCORE, RISK_FACTORS, RISK_SUGGESTIONS, ASSESSOR_ID, ASSESSOR_NAME, ASSESSMENT_DATE, CREATE_TIME, UPDATE_TIME FROM TBL_BILL_RISK_ASSESSMENT WHERE DELETE_FLAG = 0
AND BILL_NUMBER LIKE CONCAT('%', #{query.billNumber}, '%')
AND RISK_LEVEL = #{query.riskLevel}
AND RISK_SCORE >= #{query.riskScoreMin}
AND RISK_SCORE <= #{query.riskScoreMax}
AND ASSESSOR_NAME LIKE CONCAT('%', #{query.assessorName}, '%')
AND ASSESSMENT_DATE >= #{query.assessmentDateStart}
AND ASSESSMENT_DATE <= #{query.assessmentDateEnd}
ORDER BY ASSESSMENT_DATE DESC
